import asyncio
import atexit
import multiprocessing as mp
import os
import threading
import time
from collections import deque
from collections.abc import Callable
from concurrent.futures import ProcessPoolExecutor
from concurrent.futures.process import BrokenProcessPool
from contextlib import asynccontextmanager
from functools import partial

from areal.utils import logging

# Default 'fork' inherits the rollout worker's huge PyTorch/SGLang heap into
# every reward worker. Even when the rewards are tiny and the pool is idle,
# CoW page duplication grows each worker to >100 GB after an hour, eventually
# tripping Ray's 98% host-RAM kill. 'spawn' starts each worker via exec() so
# it begins with ~50 MB instead of inheriting parent state. (2026-06-02 fix
# for repeated host-OOM kills in our DAPO runs.)
_MP_SPAWN_CTX = mp.get_context("spawn")

logger = logging.getLogger("RewardAPI")


class _SharedAsyncCapacityLimiter:
    """A fair async limiter that can safely be shared across event loops.

    ``AsyncRewardWrapper`` shares one process pool between wrapper instances
    with the same worker count. An ``asyncio.Semaphore`` per event loop would
    therefore over-admit work whenever more than one loop uses that pool. This
    limiter keeps the capacity counter and FIFO queue behind a threading lock,
    while waiters yield cooperatively and remain immediately cancellable.
    """

    def __init__(self, capacity: int):
        if capacity < 1:
            raise ValueError(f"capacity must be positive, got {capacity}")
        self.capacity = capacity
        self._available = capacity
        self._waiters = deque()
        self._lock = threading.Lock()

    @asynccontextmanager
    async def slot(self):
        token = object()
        acquired = False
        with self._lock:
            self._waiters.append(token)
        try:
            while True:
                with self._lock:
                    if (
                        self._available > 0
                        and self._waiters
                        and self._waiters[0] is token
                    ):
                        self._waiters.popleft()
                        self._available -= 1
                        acquired = True
                        break
                await asyncio.sleep(0.01)
            yield
        finally:
            with self._lock:
                if acquired:
                    self._available += 1
                    if self._available > self.capacity:
                        raise RuntimeError("reward capacity limiter released too often")
                else:
                    try:
                        self._waiters.remove(token)
                    except ValueError:
                        pass


def _get_device_count_safely() -> int:
    """
    Safely get device count without initializing CUDA context.
    """
    gpu_types = ["nvidia", "davinci"]
    try:
        if os.path.exists("/dev"):
            for gpu_type in gpu_types:
                devices = [
                    f
                    for f in os.listdir("/dev")
                    if f.startswith(gpu_type) and f[len(gpu_type) :].isdigit()
                ]
                if devices:
                    return len(devices)
    except (OSError, ValueError) as e:
        # /dev doesn't exist or can't read (e.g., Windows, macOS)
        logger.debug(f"Could not read device list from /dev, using fallback: {e}")

    # Fallback: assume 8 devices for cautious max_workers calculation
    return 8


def reward_fn(
    prompt: str,
    completions: str,
    prompt_ids: list[int],
    completion_ids: list[int],
    **kwargs,
):
    """This function is a placeholder for the reward function that will be used in the RLVR pipeline.

    In general, there's no restriction on the signature and implementation of this function in customized rollout workflows.
    It would be convinent to follow this signature and directly use it in our predefined rollout workflows.

    :param prompt: The string representing the task to be completed.
    :param completions: The string representing the trajectory generated by the model.
    :param prompt_ids: The token IDs of the prompt.
    :param completion_ids: The token IDs of the trajectory generated by the model.
    :param kwargs: Other attributes of the data in the dataset, such as solutions, input_outputs, etc.
        Any other attributes in the dataset will be passed as keyword arguments to this function.
    :rtype: float
    """


class AsyncRewardWrapper:
    """Wraps a synchronous reward function for async execution with timeout and retries.

    Executors are shared by ``max_workers`` key and cleaned up via ``atexit``.
    Includes automatic recovery from broken process pools.

    The reward function and its arguments must be picklable since they
    are dispatched to worker processes via ``ProcessPoolExecutor``.
    """

    _executors: dict[int, ProcessPoolExecutor] = {}
    _limiters: dict[int, _SharedAsyncCapacityLimiter] = {}
    _poisoned_executor_keys: set[int] = set()
    _lock = threading.Lock()
    _atexit_registered = False

    def __init__(
        self,
        reward_fn: Callable,
        timeout_seconds: float | None = None,
        max_workers: int | None = None,
        max_retries: int = 3,
    ):
        self.reward_fn = reward_fn
        if timeout_seconds is None:
            # AREAL_REWARD_TIMEOUT_SECONDS lets rollout-debug runs bump the
            # post-admission timeout above the 15 s default without touching
            # production callers. Default preserves prior behavior.
            timeout_seconds = float(
                os.environ.get("AREAL_REWARD_TIMEOUT_SECONDS", "15")
            )
        self.timeout_seconds = timeout_seconds
        if max_workers is None:
            cpu_count = os.cpu_count() or 1
            device_count = _get_device_count_safely()
            max_workers = max((cpu_count // device_count) // 2, 1)
        self.max_workers = max_workers
        self.max_retries = max_retries
        self._executor_key = max_workers

        with self._lock:
            if self._executor_key in self._poisoned_executor_keys:
                raise RuntimeError(
                    "Reward ProcessPoolExecutor is poisoned after an unclean "
                    f"retirement: max_workers={self._executor_key}"
                )
            if self._executor_key not in self._executors:
                # max_tasks_per_child=20: recycle each spawn-context worker
                # every ~20 verify calls so
                # the C-level state in math_verify / sympy / latex2sympy2_extended
                # (gmpy2 caches, ANTLR parser tables, etc.) cannot grow
                # unbounded. A larger recycle interval allowed a pathological
                # verifier call to retain enough native-library state to cross
                # the worker's memory budget before retirement. Recycling
                # after 20 tasks bounds that accumulation while amortizing
                # process-spawn overhead across multiple calls.
                # Spawn overhead is bounded by the worker lifecycle and is
                # acceptable compared with the fail-closed memory ceiling.
                # Python 3.11+ stdlib parameter, supported in 3.12 container.
                self._executors[self._executor_key] = ProcessPoolExecutor(
                    max_workers=max_workers,
                    mp_context=_MP_SPAWN_CTX,
                    max_tasks_per_child=20,
                )
            if not AsyncRewardWrapper._atexit_registered:
                atexit.register(AsyncRewardWrapper._atexit_shutdown_all)
                AsyncRewardWrapper._atexit_registered = True

    @classmethod
    def _atexit_shutdown_all(cls):
        """Shut down all executors before ``_python_exit`` to prevent
        worker processes deadlocking in ``_finalize_join``.
        Must use ``wait=True`` so the result queue is fully drained.
        """
        with cls._lock:
            for executor in cls._executors.values():
                try:
                    executor.shutdown(wait=True, cancel_futures=True)
                except Exception as e:
                    logger.warning(f"Error shutting down executor at exit: {e}")
            cls._executors.clear()
            cls._limiters.clear()

    @classmethod
    def _get_limiter(
        cls, executor_key: int, max_workers: int
    ) -> _SharedAsyncCapacityLimiter:
        """Limit submissions globally for the corresponding shared executor."""
        with cls._lock:
            limiter = cls._limiters.get(executor_key)
            if limiter is None:
                limiter = _SharedAsyncCapacityLimiter(max_workers)
                cls._limiters[executor_key] = limiter
            elif limiter.capacity != max_workers:
                raise RuntimeError(
                    "reward executor and submission limiter capacities disagree: "
                    f"executor_key={executor_key}, limiter={limiter.capacity}, "
                    f"requested={max_workers}"
                )
            return limiter

    @classmethod
    def _replace_timed_out_executor(
        cls,
        executor_key: int,
        max_workers: int,
        timed_out: ProcessPoolExecutor,
    ) -> ProcessPoolExecutor | None:
        """Terminate a stuck reward pool and atomically replace it.

        Python 3.12 has no public immediate-termination API for
        ``ProcessPoolExecutor``.  A timed-out verifier may keep running
        indefinitely, so a non-waiting shutdown alone would leave the only
        worker poisoned.  Terminate the executor's owned child processes
        before replacing the pool; the private process mapping is guarded and
        used only for this fail-closed recovery path.
        """
        with cls._lock:
            current = cls._executors.get(executor_key)
            if current is not timed_out:
                return current

            # Remove the poisoned identity before any blocking teardown. Calls
            # submit under the same class lock, so none can race a new task
            # into this executor after the compare-and-swap succeeds.
            cls._executors.pop(executor_key, None)
            processes = list((getattr(timed_out, "_processes", None) or {}).values())
            manager_thread = getattr(timed_out, "_executor_manager_thread", None)
            for process in processes:
                try:
                    process.terminate()
                except Exception as exc:
                    logger.warning(f"Error terminating timed-out reward worker: {exc}")

            terminate_deadline = time.monotonic() + 1.0
            for process in processes:
                try:
                    process.join(
                        timeout=max(0.0, terminate_deadline - time.monotonic())
                    )
                except Exception as exc:
                    logger.warning(f"Error joining terminated reward worker: {exc}")

            stubborn = []
            for process in processes:
                try:
                    if process.is_alive():
                        process.kill()
                        stubborn.append(process)
                except Exception as exc:
                    logger.warning(f"Error killing timed-out reward worker: {exc}")

            kill_deadline = time.monotonic() + 1.0
            for process in stubborn:
                try:
                    process.join(timeout=max(0.0, kill_deadline - time.monotonic()))
                except Exception as exc:
                    logger.warning(f"Error joining killed reward worker: {exc}")

            manager_alive = False
            if (
                manager_thread is not None
                and manager_thread is not threading.current_thread()
            ):
                try:
                    manager_thread.join(timeout=1.0)
                    manager_alive = manager_thread.is_alive()
                except Exception as exc:
                    logger.warning(f"Error joining reward executor manager: {exc}")
                    manager_alive = True

            # The manager thread and this recovery path can concurrently reap
            # the same multiprocessing.Process objects.  Before the manager
            # publishes its final returncode, Process.is_alive() can briefly
            # report a stale survivor (for example after waitpid sees ECHILD).
            # Synchronize with the manager first, then re-join every original
            # process and compute the only survivor set used for poisoning.
            final_reap_deadline = time.monotonic() + 1.0
            for process in processes:
                try:
                    process.join(
                        timeout=max(0.0, final_reap_deadline - time.monotonic())
                    )
                except Exception as exc:
                    logger.warning(
                        f"Error in final join of timed-out reward worker: {exc}"
                    )

            if (
                manager_alive
                and manager_thread is not None
                and manager_thread is not threading.current_thread()
            ):
                try:
                    manager_thread.join(timeout=0)
                    manager_alive = manager_thread.is_alive()
                except Exception as exc:
                    logger.warning(
                        f"Error refreshing reward executor manager state: {exc}"
                    )
                    manager_alive = True

            survivors = []
            for process in processes:
                try:
                    if process.is_alive():
                        survivors.append(process.pid)
                except Exception as exc:
                    logger.warning(f"Error checking timed-out reward worker: {exc}")
                    survivors.append(getattr(process, "pid", None))

            if survivors or manager_alive:
                cls._poisoned_executor_keys.add(executor_key)
                logger.error(
                    "Timed-out reward executor did not retire cleanly: "
                    f"surviving_workers={survivors}, manager_alive={manager_alive}"
                )
                return None

            # ProcessPoolExecutor.shutdown(wait=False) still takes the pool's
            # private shutdown lock.  Calling it before the manager thread has
            # exited can deadlock with the manager's broken-pool teardown and
            # prevent the kill fallback above from ever running.  Once both
            # workers and manager are confirmed gone, reference cleanup is
            # non-blocking and safe.
            try:
                timed_out.shutdown(wait=False, cancel_futures=True)
            except Exception as exc:
                logger.warning(f"Error shutting down timed-out reward executor: {exc}")

            try:
                replacement = ProcessPoolExecutor(
                    max_workers=max_workers,
                    mp_context=_MP_SPAWN_CTX,
                    max_tasks_per_child=20,
                )
            except Exception:
                logger.exception("Failed to replace timed-out ProcessPoolExecutor")
                cls._executors.pop(executor_key, None)
                return None

            cls._executors[executor_key] = replacement
            cls._poisoned_executor_keys.discard(executor_key)
            logger.info(
                f"Replaced timed-out ProcessPoolExecutor with {max_workers} workers"
            )
            return replacement

    @classmethod
    def _recreate_executor(
        cls,
        executor_key: int,
        max_workers: int,
        broken: ProcessPoolExecutor,
    ) -> ProcessPoolExecutor | None:
        with cls._lock:
            current = cls._executors.get(executor_key)
            if current is not broken:
                return current
            try:
                broken.shutdown(wait=False)
            except Exception as e:
                logger.warning(f"Error shutting down broken executor: {e}")
            try:
                # See companion construction above for the max_tasks_per_child=20
                # rationale; mirroring it here so the BrokenProcessPool-recreate
                # path inherits the same per-worker C-state ceiling.
                new_executor = ProcessPoolExecutor(
                    max_workers=max_workers,
                    mp_context=_MP_SPAWN_CTX,
                    max_tasks_per_child=20,
                )
            except Exception:
                logger.exception("Failed to create replacement ProcessPoolExecutor")
                cls._executors.pop(executor_key, None)
                return None
            cls._executors[executor_key] = new_executor
            logger.info(f"Recreated ProcessPoolExecutor with {max_workers} workers")
            return new_executor

    async def __call__(self, *args, **kwargs) -> float:
        limiter = self._get_limiter(self._executor_key, self.max_workers)
        for attempt in range(self.max_retries + 1):
            async with limiter.slot():
                is_last = attempt == self.max_retries
                try:
                    with self._lock:
                        executor = self._executors.get(self._executor_key)
                        if executor is None:
                            raise RuntimeError("ProcessPoolExecutor has been shut down")
                        concurrent_future = executor.submit(
                            partial(self.reward_fn, *args, **kwargs)
                        )
                except BrokenProcessPool:
                    logger.warning(
                        f"ProcessPoolExecutor broken while submitting reward "
                        f"(attempt {attempt + 1}/{self.max_retries + 1}). "
                        "Attempting to recreate..."
                    )
                    if is_last:
                        raise
                    if (
                        self._recreate_executor(
                            self._executor_key, self.max_workers, executor
                        )
                        is None
                    ):
                        raise
                    continue
                except Exception:
                    logger.exception(
                        f"Reward submission error (attempt {attempt + 1}/"
                        f"{self.max_retries + 1})"
                    )
                    if is_last:
                        raise
                    continue

                async_future = asyncio.wrap_future(concurrent_future)
                try:
                    done, _ = await asyncio.wait(
                        {async_future}, timeout=self.timeout_seconds
                    )
                except asyncio.CancelledError:
                    cancelled_before_start = concurrent_future.cancel()
                    async_future.cancel()
                    if not cancelled_before_start and not concurrent_future.done():
                        self._replace_timed_out_executor(
                            self._executor_key,
                            self.max_workers,
                            executor,
                        )
                    raise

                if not done:
                    cancelled_before_start = concurrent_future.cancel()
                    async_future.cancel()
                    if not cancelled_before_start and not concurrent_future.done():
                        self._replace_timed_out_executor(
                            self._executor_key,
                            self.max_workers,
                            executor,
                        )
                    logger.warning(
                        f"Computing reward timeout after {self.timeout_seconds}s "
                        f"(attempt {attempt + 1}/{self.max_retries + 1}). "
                        f"{'Failing closed.' if is_last else 'Retrying...'}"
                    )
                    if is_last:
                        raise TimeoutError(
                            f"Reward computation exceeded {self.timeout_seconds}s"
                        )
                    continue

                try:
                    return async_future.result()
                except BrokenProcessPool:
                    logger.warning(
                        f"ProcessPoolExecutor broken (attempt {attempt + 1}/{self.max_retries + 1}). "
                        "Attempting to recreate..."
                    )
                    if is_last:
                        raise
                    if (
                        self._recreate_executor(
                            self._executor_key, self.max_workers, executor
                        )
                        is None
                    ):
                        raise
                except Exception:
                    logger.exception(
                        f"Reward computation error (attempt {attempt + 1}/{self.max_retries + 1})"
                    )
                    if is_last:
                        raise

        raise RuntimeError("Reward computation exhausted retries without a result")
